function gcd(a, b) {
  while (b !== 0) {
    const r = a % b;
    a = b;
    b = r;
  }
  return a;
}

console.log(gcd(48, 18));
console.log(gcd(17, 5));

function neverStops(n) {
  let steps = 0;
  while (n > 0) {
    n = n + 1;
    steps = steps + 1;
    if (steps === 5) return "gave up after " + steps + " steps";
  }
  return String(n);
}

