function reverseCopy(arr) {
  const out = [];
  for (let i = arr.length - 1; i >= 0; i--) out.push(arr[i]);
  return out;
}

function reverseInPlace(arr) {
  let i = 0;
  let j = arr.length - 1;
  while (i < j) {
    const t = arr[i];
    arr[i] = arr[j];
    arr[j] = t;
    i = i + 1;
    j = j - 1;
  }
  return arr;
}

