function bubbleSort(input) {
  const a = input.slice();
  for (let i = 0; i < a.length - 1; i++) {
    let swapped = false;
    for (let j = 0; j < a.length - 1 - i; j++) {
      if (a[j] > a[j + 1]) {
        const t = a[j];
        a[j] = a[j + 1];
        a[j + 1] = t;
        swapped = true;
      }
    }
    console.log("after pass " + (i + 1) + ": " + JSON.stringify(a));
    if (!swapped) break;
  }
  return a;
}

