checkpoint.solution:
function insertAt(sorted, key) {
  const a = sorted.slice();
  a.push(key);
  let j = a.length - 2;
  while (j >= 0 && a[j] > key) {
    a[j + 1] = a[j];
    j--;
  }
  a[j + 1] = key;
  return a;
}

