function isBST(root) {
  function ok(n, low, high) {
    if (n === null) return true;
    if (low !== null && n.value <= low) return false;
    if (high !== null && n.value >= high) return false;
    return ok(n.left, low, n.value) && ok(n.right, n.value, high);
  }
  return ok(root, null, null);
}

