function nodesAtDistance(graph, start, d) {
  const visited = new Set([start]);
  const dist = { [start]: 0 };
  const queue = [start];
  const out = [];
  while (queue.length > 0) {
    const node = queue.shift();
    if (dist[node] === d) out.push(node);
    for (const nb of graph[node] || []) {
      if (visited.has(nb)) continue;
      visited.add(nb);
      dist[nb] = dist[node] + 1;
      queue.push(nb);
    }
  }
  return out.sort();
