function farthestDistance(graph, start) {
  const visited = new Set([start]);
  const dist = { [start]: 0 };
  const queue = [start];
  let best = 0;
  while (queue.length > 0) {
    const node = queue.shift();
    if (dist[node] > best) best = dist[node];
    for (const nb of graph[node] || []) {
      if (visited.has(nb)) continue;
      visited.add(nb);
      dist[nb] = dist[node] + 1;
      queue.push(nb);
    }
  }
  return best;
}

