function parseQuery(query) {
  const parsed = { required: [], optional: [], excluded: [] };
  const seen = [];
  for (const word of String(query).split(/\s+/).filter(Boolean)) {
    let bucket = "optional", rest = word;
    if (word[0] === "+") { bucket = "required"; rest = word.slice(1); }
    else if (word[0] === "-") { bucket = "excluded"; rest = word.slice(1); }
    for (const term of tokenise(rest)) {
      if (seen.indexOf(term) >= 0) continue;
      seen.push(term);
      parsed[bucket].push(term);
    }
  }
  return parsed;
}

